/* Full-viewport map. No browser fullscreen permission and no locked course nodes. */
let mapOrigin='home';
// Positions follow the clear foreground at the foot of each new landmark.
[[16,30],[39,27],[65,32],[89,29],[85,73],[62,80],[39,73],[16,80]].forEach(([x,y],i)=>Object.assign(journeyStops[i],{x,y}));
const mapSession={zoom:1,scrollX:0,scrollY:0,hasCamera:false,intro:true,selected:null,baseWidth:0};
let mapResizeObserver=null,entryTimer=0,draggedMap=false;
const reducedMotion=()=>window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function rememberMap(){const stage=$('#realm-stage');if(stage){mapSession.scrollX=stage.scrollLeft;mapSession.scrollY=stage.scrollTop;mapSession.hasCamera=true;}mapResizeObserver?.disconnect();}
function realmPanel(index){const w=weeks[index];return `<div class="realm-panel-top"><span>WEEK ${String(index+1).padStart(2,'0')}</span><button data-realm="close-panel" aria-label="收起本周任务">${icon('close',18)}</button></div><h2 id="realm-week-title">${w[0]}</h2>${index===0?`<p>两个任务，各自留下第一版。</p><div class="realm-missions">${Object.entries(taskCatalog).map(([id,t])=>`<button data-go="task/${id}"><img src="${expeditionAssets}navigation/${t.art}.webp" alt="" width="40" height="40"><span><strong>${t.short}</strong><small>${taskState(id)}</small></span><span>↗</span></button>`).join('')}</div>`:`<p>${journeyStops[index].deliverable}</p><span class="status-chip">任务未发布</span>`}${routeButton('week/'+(index+1),index===0?'打开 W1 任务页 ↗':`查看 W${index+1} 安排 ↗`,'primary')}`;}
function realmPage(){return `<section class="realm ${mapSession.intro&&!reducedMotion()?'realm-entering':''}" aria-label="八周旅程全屏地图"><div class="realm-header"><button class="realm-exit" data-realm="exit">${icon('close',18)}<span>退出地图</span></button><div class="realm-title"><span>THE BUILDER'S ATLAS</span><strong>八周创造之旅</strong></div><button class="realm-skip" data-realm="skip" ${mapSession.intro&&!reducedMotion()?'':'hidden'}>跳过入场</button></div><div id="realm-stage" class="realm-stage" tabindex="0" aria-label="可拖动的地图，也可用下方周次按钮定位"><div id="realm-surface" class="realm-surface"><img class="realm-landscape" ${artSources(expeditionAssets+'journey-world-v2.webp')} alt="八个地标环绕湖泊、由石路相连的清晰像素冒险地图" width="1536" height="1024" draggable="false" fetchpriority="high">${journeyStops.map((s,i)=>`<button class="realm-node ${i===0?'current':''} ${mapSession.selected===i?'selected':''}" style="left:${s.x}%;top:${s.y}%" data-realm-week="${i}" aria-label="W${i+1} ${weeks[i][0]}${i===0?'，你在这里':''}" aria-expanded="${mapSession.selected===i}" aria-controls="realm-detail">${i===0?`<span class="realm-player" aria-hidden="true"><span class="realm-player-shadow"></span><span class="realm-player-float">${myAvatar('realm-player-avatar')}</span></span>`:`<span class="realm-pin">${String(i+1).padStart(2,'0')}</span>`}<strong><b>W${i+1}</b> ${weeks[i][0]}</strong>${i===0?'<small>你在这里</small>':''}</button>`).join('')}</div></div><aside id="realm-detail" class="realm-detail" role="region" aria-labelledby="realm-week-title" ${mapSession.selected===null?'hidden':''}>${mapSession.selected===null?'':realmPanel(mapSession.selected)}</aside><div class="realm-zoom" aria-label="地图缩放"><button data-realm="zoom-in" aria-label="放大地图">+</button><output id="realm-scale" aria-label="地图缩放比例">100%</output><button data-realm="zoom-out" aria-label="缩小地图">−</button><button data-realm="overview" aria-label="查看全图">${icon('map',18)}</button></div><div class="realm-bottom"><div class="realm-help"><span>拖动探索 · 点击路标看任务</span><button data-realm="current">定位 W1</button></div><nav class="realm-weeks" aria-label="快速选择周次">${weeks.map((w,i)=>`<button data-realm-week="${i}" aria-label="定位 W${i+1} ${w[0]}" ${mapSession.selected===i?'aria-current="true"':''}>W${i+1}</button>`).join('')}</nav></div><p class="realm-announcement" aria-live="polite" id="realm-announcement"></p></section>`;}
function sizeMap(){const stage=$('#realm-stage'),surface=$('#realm-surface');if(!stage||!surface)return;mapSession.baseWidth=Math.max(stage.clientWidth,stage.clientHeight*1.5);surface.style.width=Math.round(mapSession.baseWidth*mapSession.zoom)+'px';surface.style.height=Math.round(mapSession.baseWidth*mapSession.zoom/1.5)+'px';$('#realm-scale').value=Math.round(mapSession.zoom*100)+'%';}
function centerMapNode(index,behavior='smooth'){const stage=$('#realm-stage'),surface=$('#realm-surface');if(!stage||!surface)return;const s=journeyStops[index];stage.scrollTo({left:surface.offsetLeft+surface.offsetWidth*s.x/100-stage.clientWidth*(stage.clientWidth>760&&mapSession.selected!==null?.36:.5),top:surface.offsetTop+surface.offsetHeight*s.y/100-stage.clientHeight*(mapSession.selected!==null?.32:.45),behavior:reducedMotion()?'instant':behavior});}
function zoomMap(next,overview=false){const stage=$('#realm-stage'),surface=$('#realm-surface');if(!stage||!surface)return;const cx=(stage.scrollLeft+stage.clientWidth/2-surface.offsetLeft)/surface.offsetWidth,cy=(stage.scrollTop+stage.clientHeight/2-surface.offsetTop)/surface.offsetHeight;mapSession.zoom=Math.max(.2,Math.min(2,next));sizeMap();if(overview){stage.scrollTo({left:0,top:0});}else{stage.scrollTo({left:surface.offsetLeft+surface.offsetWidth*cx-stage.clientWidth/2,top:surface.offsetTop+surface.offsetHeight*cy-stage.clientHeight/2});}}
function skipEntry(){const realm=$('.realm');if(realm){realm.classList.remove('realm-entering');const skip=$('[data-realm="skip"]');if(skip)skip.hidden=true;}mapSession.intro=false;}
function mountMap(){if(page!=='map')return;mapResizeObserver?.disconnect();sizeMap();const stage=$('#realm-stage');if(mapSession.hasCamera)stage.scrollTo({left:mapSession.scrollX,top:mapSession.scrollY});else centerMapNode(0,'instant');clearTimeout(entryTimer);entryTimer=setTimeout(skipEntry,850);const width=stage.clientWidth,height=stage.clientHeight;mapResizeObserver=new ResizeObserver(()=>{if(!$('#realm-stage'))return;if(stage.clientWidth!==width||stage.clientHeight!==height)sizeMap();});mapResizeObserver.observe(stage);let drag=null;
 stage.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0||e.target.closest('button'))return;drag={x:e.clientX,y:e.clientY,left:stage.scrollLeft,top:stage.scrollTop};draggedMap=false;stage.setPointerCapture(e.pointerId);stage.classList.add('dragging');});
 stage.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>4)draggedMap=true;stage.scrollLeft=drag.left-dx;stage.scrollTop=drag.top-dy;});
 const stopDrag=()=>{drag=null;stage.classList.remove('dragging');};stage.addEventListener('pointerup',stopDrag);stage.addEventListener('pointercancel',stopDrag);
 stage.addEventListener('keydown',e=>{if(e.target!==stage)return;const moves={ArrowLeft:[-90,0],ArrowRight:[90,0],ArrowUp:[0,-90],ArrowDown:[0,90]};if(moves[e.key]){e.preventDefault();stage.scrollBy({left:moves[e.key][0],top:moves[e.key][1],behavior:reducedMotion()?'instant':'smooth'});}});
 $('[data-realm="exit"]').focus({preventScroll:true});
}
function selectRealmWeek(index){if(!Number.isInteger(index)||index<0||index>7)return;mapSession.selected=index;skipEntry();document.querySelectorAll('.realm-node').forEach(b=>{const selected=Number(b.dataset.realmWeek)===index;b.classList.toggle('selected',selected);b.setAttribute('aria-expanded',String(selected));});document.querySelectorAll('.realm-weeks button').forEach(b=>{if(Number(b.dataset.realmWeek)===index)b.setAttribute('aria-current','true');else b.removeAttribute('aria-current');});const panel=$('#realm-detail');panel.innerHTML=realmPanel(index);panel.hidden=false;centerMapNode(index);$('#realm-announcement').textContent=`已打开 W${index+1} ${weeks[index][0]}，${index===0?'包含个人网站和个人知识库两项任务':'任务未发布'}`;}
function closeRealmPanel(){const previous=mapSession.selected;mapSession.selected=null;$('#realm-detail').hidden=true;document.querySelectorAll('.realm-node').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-expanded','false');});document.querySelectorAll('.realm-weeks button').forEach(b=>b.removeAttribute('aria-current'));if(previous!==null)$(`.realm-node[data-realm-week="${previous}"]`)?.focus({preventScroll:true});}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||page!=='map')return;if(b.dataset.realmWeek!==undefined){selectRealmWeek(Number(b.dataset.realmWeek));return;}const action=b.dataset.realm;if(action==='exit')go(validRoute(mapOrigin)&&mapOrigin!=='map'?mapOrigin:'home');if(action==='skip')skipEntry();if(action==='close-panel')closeRealmPanel();if(action==='zoom-in')zoomMap(mapSession.zoom+.2);if(action==='zoom-out')zoomMap(mapSession.zoom-.2);if(action==='overview'){const stage=$('#realm-stage');zoomMap(Math.min(stage.clientWidth/mapSession.baseWidth,stage.clientHeight/(mapSession.baseWidth/1.5)),true);}if(action==='current')selectRealmWeek(0);});
document.addEventListener('keydown',e=>{if(page==='map'&&e.key==='Escape'&&!$('#modal-root').firstElementChild){e.preventDefault();if(mapSession.selected!==null)closeRealmPanel();else go(mapOrigin==='map'?'home':mapOrigin);}});
page=validRoute(location.hash.slice(1))?location.hash.slice(1):'home';
render();
